import { useState, useCallback } from "react";
import { TestProgressHeader } from "../shared/UI";
import { useLang } from "../../store/langContext";

function randomPositions(count, size = 280) {
  return Array.from({ length: count }, () => ({
    x: Math.random() * size,
    y: Math.random() * size
  }));
}

export default function TrailMaking({ onComplete, testIndex, totalTests }) {
  const { t } = useLang();

  const [part, setPart] = useState("A");
  const [started] = useState(Date.now());

  const nodes = randomPositions(10);

  const handleComplete = useCallback(() => {
    const time = Math.round((Date.now() - started) / 1000);
    onComplete({ score: 5, maxScore: 5, timeTaken: time });
  }, [started, onComplete]);

  return (
    <div className="page-enter">
      <TestProgressHeader
        current={testIndex + 1}
        total={totalTests}
        testName={t("trail_name")}
      />

      <div className="card text-center">
        <p>
          {part === "A"
            ? t("trail_instruction_A")
            : t("trail_instruction_B")}
        </p>

        <button onClick={handleComplete}>
          {t("trail_finish")}
        </button>
      </div>
    </div>
  );
}
